code.cpp:
class Solution {
public:
    int mostFrequentEven(vector<int>& nums) {
        unordered_map<int,int> cnt;
        for (int x : nums) {
            if (x % 2 == 0) cnt[x]++;
        }
        int ans = -1, best = 0;
        for (auto& [v, c] : cnt) {
            if (c > best || (c == best && v < ans)) {
                best = c;
                ans = v;
            }
        }
        return ans;
    }
};
